import{_ as e,o as a,c as t,ag as _}from"./chunks/framework.Ddwm6YJC.js";const m=JSON.parse('{"title":"第二卷 回潮 · 第34章 接力","description":"","frontmatter":{},"headers":[],"relativePath":"第34章_接力.md","filePath":"第34章_接力.md"}'),r={name:"第34章_接力.md"};function o(n,p,s,c,i,d){return a(),t("div",null,[...p[0]||(p[0]=[_('<h1 id="第二卷-回潮-·-第34章-接力" tabindex="-1">第二卷 回潮 · 第34章 接力 <a class="header-anchor" href="#第二卷-回潮-·-第34章-接力" aria-label="Permalink to &quot;第二卷 回潮 · 第34章 接力&quot;">​</a></h1><p>运动会放在开学后那个秋天，风有了凉意，太阳依旧很亮。</p><p>操场一早就满了人，彩旗被风扯得哗哗响，跑道晒出暖暖的味道，混着烤肠的香气，到处飘。</p><p>我们班的接力跑排在午后，名单贴在帐篷边上，我看了一眼，最后一棒是江苒。</p><p>秦浩从后面拍我肩膀，说最后一棒是江苒，你就没点表示。</p><p>我说，好好加油就是表示。</p><p>他啧了一声，说水呢，毛巾呢，终点的位置呢，你占了吗。</p><p>我摇头，他瞪眼，说走，去小卖部，现在就去。</p><p>小卖部挤满了人，冰柜前全是脑袋，冷气扑在脸上，很舒服。</p><p>秦浩挤进去，拿出两瓶水，一瓶橘子汽水留给自己，一瓶薄荷水塞给我。</p><p>他说，喏，江苒喜欢喝这个，跑完喝最解渴。</p><p>我握着那瓶水，瓶身冰凉，掌心很快沾上一层水汽。</p><p>秦浩正好路过，怀里抱着一摞号码布，额头全是汗。</p><p>他扬起下巴，说呦，买水呢，给谁买的。</p><p>秦浩立刻说，给沈聿心上人买的，你别多问。</p><p>秦浩拖长调子哦了一声，说我懂，我就是路过打酱油的，你们继续。</p><p>我说，你别听他胡说，就是同学之间递瓶水。</p><p>秦浩笑着摆手，说行，纯洁的同学情，我先去发号码布，回头来看冲刺。</p><p>他走出几步又回头，冲我眨眼，说终点人多，早点去占个好位置。</p><p>午后太阳斜了一些，跑道被照得发白，哨声一声接一声，欢呼一阵高过一阵。</p><p>女子接力开始检录，林小满陪着江苒过来，她穿着运动短袖，头发扎成高马尾。</p><p>她手腕系着细细的红绳，坠着一颗小铃铛，走动起来发出很轻的响声。</p><p>林小满挥手，说沈聿你也在，正好，帮我们拿下外套。</p><p>我接过外套抱在怀里，还带着太阳晒过的温度。</p><p>江苒抬头看我，眼睛亮亮的，额头有一层薄汗。</p><p>她说，你如何在这里，不去看男子跑吗。</p><p>我说，等会儿再去，先看你们跑。</p><p>秦浩插话，说他专门来看你的，终点都踩好点了，水都冰好了。</p><p>江苒目光落在我手里的薄荷水上，唇角慢慢弯起来。</p><p>她说，原来你还记得我喜欢喝这个。</p><p>我点头，耳根有点烫，说嗯，上次听你提过一次。</p><p>她笑起来，说你记性真好，我自己都快忘了。</p><p>发令枪响之前，操场安静了一瞬，接着满场都是加油声。</p><p>第一棒出发很顺，我们班的姑娘跑得飞快，交接也很稳，看台立刻沸腾起来。</p><p>我抱着外套往终点走，秦浩在前面开路，一边走一边喊，借过借过，递水的人来了。</p><p>终点附近挤满了人，空气里全是汗味和防晒霜的味道，有人举着冰棍，甜丝丝的凉气直往鼻子里钻。</p><p>我找了个靠近跑道的位置站定，手心全是汗。</p><p>秦浩喝了一大口橘子汽水，说别紧张，你手抖的，水都快拿不住了。</p><p>我说，我没紧张，就是有点热。</p><p>交接区一阵骚动，最后一棒几乎同时冲了出去。</p><p>江苒接棒很利落，手指紧扣接力棒，马尾在脑后甩成弧线。</p><p>风迎面扑去，阳光在她皮肤上跳动，衣摆被风掀起来，又落回去。</p><p>铃铛声被风扯碎了，我却觉得听得很清楚，清脆的一串，跟着她的脚步往前赶。</p><p>全场都在喊她的名字，声音一层叠一层，震得我胸口发闷。</p><p>林小满在看台上跳起来喊，江苒加油，冲啊。</p><p>我张了张嘴，嗓子有点干，喊出来的声音不大，却用了全力。</p><p>我说，江苒加油。</p><p>她好像听见了，视线往我这边扫了一眼，很快收回去，脚下更快了。</p><p>弯道过后，她和隔壁跑道的姑娘几乎并排，发丝被汗粘在脸颊上，嘴唇抿得很紧。</p><p>秦浩在我耳边大叫，说超她，直道加速啊。</p><p>我心跳得厉害，手里的薄荷水被捏得咯吱响。</p><p>最后几步，江苒猛地摆臂，肩膀往前一探，真的超过去半个身位。</p><p>终点线被她踩过去的瞬间，看台爆发出巨大欢呼，彩旗被风卷起来，像翻涌的海。</p><p>她冲过终点又缓了几步，才停下来，双手撑着膝盖，大口喘气，汗水顺着下巴往下滴。</p><p>我脑子一热，抱着外套跑过去，把薄荷水递到她面前。</p><p>我说，给，喝点水，慢点喝。</p><p>她抬起头，脸颊通红，接过水时指尖碰到我的手指，凉凉的，又有点烫。</p><p>她说，谢谢，你真的在终点等我啊。</p><p>我点头，把外套披到她肩上，说嗯，风大，别着凉。</p><p>秦浩冒出来，举着橘子汽水大声说，恭喜江苒，巾帼英雄，跑得太漂亮了。</p><p>江苒被他逗笑，拧开薄荷水喝了一小口，凉气让她皱了下眉，又舒展开来。</p><p>她说，好凉，好舒服，嗓子一下就通了。</p><p>陈默举着相机跑过来，喘着气说，拍到了，冲线那张特别清楚，回头洗出来送你们。</p><p>秦浩也晃悠过来，说我刚发完布就听见欢呼，紧赶慢赶还是没看到冲刺，亏大了。</p><p>秦浩拍拍他的肩，说没事，你错过冲刺，可没错过请客，江苒跑得这么好，该请喝汽水。</p><p>江苒笑着说，好啊，人人有份，我请大家喝橘子汽水。</p><p>我站在人群边上，看她笑，心里像被风吹过的湖面，一圈圈漾开。</p><p>她忽然转头看我，把喝了一半的薄荷水晃了晃。</p><p>她说，这瓶水，谢谢你，跑的时候我就在想，终点有人等着，真好。</p><p>秦浩用胳膊肘捅我，小声说，纸条呢，现在不给，更待何时。</p><p>我从口袋摸出一张折得很小的纸条，趁大家闹腾，飞快塞进她外套口袋里。</p><p>江苒似乎察觉，疑惑地看我一眼，说你刚才放了什么。</p><p>我摇头，说没什么，等你回去再看。</p><p>她眨眨眼，说神神秘秘的，好吧，那我回去看。</p><p>夕阳斜下去，操场的人渐渐散了，广播通知各班收帐篷，明天恢复上课。</p><p>回教室路上，林小满说起秋游，说听叶老师提了一嘴，今年秋天好像要去湖边写生，还能带吃的。</p><p>秦浩说，那必须的，到时候我们几个坐一辆车，热闹一路。</p><p>叶老师站在走廊上，笑着说今天大家辛苦了，回去好好休息，秋游安排过几天再公布。</p><p>林小满小声问江苒，说你秋游肯定去吧，你若缺席就没意思了。</p><p>江苒脚步顿了一下，抬头看了看天边的云。</p><p>她说，还不一定呢，家里好像有点事，到时候再看吧。</p><p>我的心一下提起来，手里的空瓶被捏得发出轻响。</p><p>风从走廊那头吹来，带着桂花的甜香，却吹不散她那句话留下的凉意。</p>',83)])])}const f=e(r,[["render",o]]);export{m as __pageData,f as default};
